toolArgs.file_text:
/* Settings Layout */
.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.sidebar-title {
    padding: 0 1.5rem;
    margin: 0 0 1rem;
    font-size: 1.25rem;
    font-weight: 600;
    color: #333;
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: all 0.2s ease;
    border-left: 3px solid transparent;
    color: #555;
}

.sidebar-item:hover {
    background: #e9ecef;
    color: #333;
}

.sidebar-item.active {
    background: #e3f2fd;
    border-left-color: #1976d2;
    color: #1976d2;
    font-weight: 500;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Main Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin: 0 0 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: #333;
}

.settings-section h3 {
    margin: 1.5rem 0 0.75rem;
    font-size: 1.1rem;
    font-weight: 600;
    color: #444;
}

/* Form Controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label,
.form-label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
    font-size: 0.9rem;
}

.form-input {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #d0d0d0;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-input:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 3px rgba(25, 118, 210, 0.1);
}

.form-textarea {
    resize: vertical;
    font-family: inherit;
}

.form-select {
    appearance: auto;
    max-width: 300px;
}

/* Buttons */
.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-primary {
    background: #1976d2;
    color: white;
}

.btn-primary:hover {
    background: #1565c0;
}

.btn-secondary {
    background: #e0e0e0;
    color: #333;
}

.btn-secondary:hover {
    background: #d0d0d0;
}

.btn-danger {
    background: #d32f2f;
    color: white;
}

.btn-danger:hover {
    background: #c62828;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Toast Messages */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease;
}

.toast-success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast-info {
    background: #e3f2fd;
    color: #1565c0;
    border: 1px solid #90caf9;
}

.toast-error {
    background: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Toggle Switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-input {
    width: 1.1rem;
    height: 1.1rem;
    accent-color: #1976d2;
}

/* Channel List */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    cursor: pointer;
    font-size: 0.9rem;
}

/* Profile Avatar */
.profile-avatar-area {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.avatar-preview {
    flex-shrink: 0;
}

.avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
}

.avatar-url-display {
    flex: 1;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
    color: #333;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

/* Security Items */
.security-item {
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.status-badge {
    padding: 0.25rem 0.6rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
}

.status-enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-disabled {
    background: #fff3e0;
    color: #e65100;
}

.security-info {
    margin: 0.5rem 0 0;
    font-size: 0.85rem;
    color: #666;
}

.current-session-badge {
    font-size: 0.8rem;
    color: #1976d2;
    font-weight: 500;
}

/* Sessions Table */
.sessions-table-wrapper {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #444;
}

.sessions-table tr:hover {
    background: #f5f5f5;
}

/* Dialog */
.dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 12px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.dialog h4 {
    margin: 0 0 0.75rem;
    font-size: 1.1rem;
}

.dialog p {
    margin: 0 0 1.25rem;
    color: #555;
    font-size: 0.9rem;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    flex-wrap: wrap;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.radio-item input[type="radio"] {
    accent-color: #1976d2;
}

/* Appearance Preview */
.preview-area {
    margin: 1.5rem 0;
    padding: 1.5rem;
    border: 2px dashed #d0d0d0;
    border-radius: 8px;
    transition: all 0.3s ease;
}

.preview-area h4 {
    margin: 0 0 0.75rem;
    color: #666;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.preview-content {
    transition: all 0.3s ease;
}

.preview-card {
    padding: 1rem;
    background: #f0f0f0;
    border-radius: 6px;
    margin: 0.75rem 0;
}

.preview-card p {
    margin: 0.4rem 0 0;
    font-size: 0.85rem;
    color: #666;
}

.preview-btn {
    margin-top: 0.75rem;
}

/* Preview Theme Variants */
.preview-theme-dark {
    background: #1e1e1e;
    border-color: #444;
    color: #e0e0e0;
}

.preview-theme-dark .preview-card {
    background: #2d2d2d;
}

.preview-theme-dark .preview-card p {
    color: #aaa;
}

.preview-theme-dark h4 {
    color: #999;
}

.preview-theme-light {
    background: #ffffff;
    border-color: #d0d0d0;
}

.preview-theme-system {
    background: #f5f5f5;
    border-color: #bbb;
}

/* Preview Font Size Variants */
.preview-font-small .preview-content {
    font-size: 0.8rem;
}

.preview-font-medium .preview-content {
    font-size: 1rem;
}

.preview-font-large .preview-content {
    font-size: 1.2rem;
}

/* Preview Compact Mode */
.preview-compact {
    padding: 0.75rem;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin: 0.4rem 0;
}

/* Loading */
.loading-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    color: #666;
    font-size: 1rem;
}

